using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.ENC.Encuestas;namespace GraphApi.Services.ENC.Encuestas{    public class EncuestasService : IEncuestasService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public EncuestasService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadEncuestas>> GetEncuestas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM enc.Encuestas (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadEncuestas>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetEncuestasDynamic(            int? encuestaID,            string? titulo,            string? descripcion,            DateTime? fechaInicio,            DateTime? fechaFin,            bool? bActivo,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "EncuestaID, Titulo, Descripcion, FechaInicio, FechaFin, bActivo, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM enc.Encuestas (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (encuestaID.HasValue)            {                vSql.Append(" AND EncuestaID = @EncuestaID");                vParameters.Add("EncuestaID",encuestaID);            }            if (!string.IsNullOrWhiteSpace(titulo))            {                vSql.Append(" AND Titulo LIKE @Titulo");                vParameters.Add("Titulo",$"%{titulo}%");            }            if (!string.IsNullOrWhiteSpace(descripcion))            {                vSql.Append(" AND Descripcion LIKE @Descripcion");                vParameters.Add("Descripcion",$"%{descripcion}%");            }            if (bActivo.HasValue)            {                vSql.Append(" AND bActivo = @bActivo");                vParameters.Add("bActivo", bActivo.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadEncuestas> CreateEncuestas(clCreateEncuestas objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO enc.Encuestas                (Titulo, Descripcion, FechaInicio, FechaFin, bActivo, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@Titulo, @Descripcion, @FechaInicio, @FechaFin, @bActivo, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.Titulo,                objInput.Descripcion,                objInput.FechaInicio,                objInput.FechaFin,                objInput.bActivo,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT EncuestaID, Titulo, Descripcion, FechaInicio, FechaFin, bActivo, bEliminado                FROM enc.Encuestas (NOLOCK)                WHERE EncuestaID = @EncuestaID;";            var vReadParams = new { EncuestaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadEncuestas>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Encuesta con ID {vNewId}.");            return vCreated;        }        public async Task<clReadEncuestas?> UpdateEncuestas(clUpdateEncuestas objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("EncuestaID", objInput.EncuestaID);            if (objInput.Titulo is not null)            {                vSets.Add("Titulo = @Titulo");                vParameters.Add("Titulo", objInput.Titulo);            }            if (objInput.Descripcion is not null)            {                vSets.Add("Descripcion = @Descripcion");                vParameters.Add("Descripcion", objInput.Descripcion);            }            if (objInput.FechaInicio != null)            {                vSets.Add("FechaInicio = @FechaInicio");                vParameters.Add("FechaInicio", objInput.FechaInicio);            }            if (objInput.FechaFin != null)            {                vSets.Add("FechaFin = @FechaFin");                vParameters.Add("FechaFin", objInput.FechaFin);            }            if (objInput.bActivo != null)            {                vSets.Add("bActivo = @bActivo");                vParameters.Add("bActivo", objInput.bActivo);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE enc.Encuestas                SET {vSetClause}                WHERE EncuestaID = @EncuestaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT EncuestaID, Titulo, Descripcion, FechaInicio, FechaFin, bActivo, bEliminado                FROM enc.Encuestas (NOLOCK)                WHERE EncuestaID = @EncuestaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadEncuestas>(sSelect, new {  objInput.EncuestaID });        }        public async Task<bool> DeleteEncuestas(int nEncuestasID)        {            const string sSql = @"                DELETE FROM enc.Encuestas                WHERE EncuestaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nEncuestasID });            return vAffected > 0;        }    }}